records = [
    {'date': '2024-01-01', 'region': 'NA', 'amount': 100, 'currency': 'USD'},
    {'date': '2024-01-02', 'region': 'EMEA', 'amount': 90, 'currency': 'EUR'},
    {'date': '2024-01-03', 'region': 'APAC', 'amount': 120, 'currency': 'USD'},
    {'date': '2024-01-04', 'region': 'EMEA', 'amount': 80, 'currency': 'GBP'}
]

exchange = {'USD': 1.0, 'EUR': 1.1, 'GBP': 1.25}

def process_sales(data, rates):
    usd_records = map(
        lambda r: {**r, 'amount_usd': r['amount'] * rates[r['currency']]},
        data
    )
    emea = filter(lambda r: r['region'] == 'EMEA', usd_records)
    from collections import defaultdict
    totals = defaultdict(float)
    for r in emea:
        totals[r['region']] += r['amount_usd']
    return dict(totals)

print(process_sales(records, exchange))

from functools import reduce

def even_product(nums):
    evens = list(filter(lambda x: x % 2 == 0, nums))
    if not evens:
        return 0
    return reduce(lambda a, b: a * b, evens)

print(even_product([2, 3, 4, 5]))
print(even_product([1, 3, 5]))
